```js
console.log('1');
setTimeout(() => console.log('2'), 0);
Promise.resolve().then(() => console.log('3'));
console.log('4');
```
**Output:** `1, 4, 3, 2`.
**Reason:** Synchronous logs (`1`, `4`) run first. `Promise.then` enters the Microtask queue (`3`), executing before `setTimeout` in the Macrotask queue (`2`).

```js
function myPromiseAll(promises) {
  return new Promise((resolve, reject) => {
    let results = [];
    let completed = 0;
    if (promises.length === 0) return resolve([]);
    promises.forEach((p, index) => {
      Promise.resolve(p)
        .then(val => {
          results[index] = val;
          completed++;
          if (completed === promises.length) resolve(results);
        })
        .catch(reject);
    });
  });
}
