Build a batcher that accumulates incoming items and flushes them to a processing function when either maximum batch size is reached OR maximum delay time elapses.

```js
class BatchScheduler {
  constructor(batchHandler, maxSize = 5, maxDelay = 100) {
    this.handler = batchHandler;
    this.maxSize = maxSize;
    this.maxDelay = maxDelay;
    this.batch = [];
    this.timer = null;
  }

  add(item) {
    this.batch.push(item);
    if (this.batch.length >= this.maxSize) {
      this.flush();
    } else if (!this.timer) {
      this.timer = setTimeout(() => this.flush(), this.maxDelay);
    }
  }

  flush() {
    if (this.timer) clearTimeout(this.timer);
    this.timer = null;
    if (this.batch.length > 0) {
      const itemsToProcess = [...this.batch];
      this.batch = [];
      this.handler(itemsToProcess);
    }
  }
}
```

Write a function `diffObjects(obj1, obj2)` returning an object highlighting updated, added, or removed properties between two objects.

```js
function diffObjects(obj1, obj2) {
  const diff = {};
  const allKeys = new Set([...Object.keys(obj1), ...Object.keys(obj2)]);

  for (let key of allKeys) {
    if (!(key in obj1)) {
      diff[key] = { status: 'ADDED', value: obj2[key] };
    } else if (!(key in obj2)) {
      diff[key] = { status: 'REMOVED', value: obj1[key] };
    } else if (typeof obj1[key] === 'object' && typeof obj2[key] === 'object' && obj1[key] !== null && obj2[key] !== null) {
      const nestedDiff = diffObjects(obj1[key], obj2[key]);
      if (Object.keys(nestedDiff).length > 0) diff[key] = nestedDiff;
    } else if (obj1[key] !== obj2[key]) {
      diff[key] = { status: 'UPDATED', oldValue: obj1[key], newValue: obj2[key] };
    }
  }
  return diff;
}
```

Implement a reactive state store that automatically runs subscriber effect functions whenever accessed state properties mutate.

```js
let activeEffect = null;

function createReactiveStore(initialState) {
  const deps = new Map(); // key -> Set of activeEffect functions

  return new Proxy(initialState, {
    get(target, key, receiver) {
      if (activeEffect) {
        if (!deps.has(key)) deps.set(key, new Set());
        deps.get(key).add(activeEffect);
      }
      return Reflect.get(target, key, receiver);
    },
    set(target, key, value, receiver) {
      const result = Reflect.set(target, key, value, receiver);
      if (deps.has(key)) {
        deps.get(key).forEach(effect => effect());
      }
      return result;
    }
  });
}

function watchEffect(effect) {
  activeEffect = effect;
  effect(); // Run initially to trigger dependency getter traps
  activeEffect = null;
}
